const DELAY=1000;
/* checkpoints live in IndexedDB (room for every conference at once); the old
   localStorage checkpoints are migrated on first use */
const KV=(function(){ function open(){ return new Promise((res,rej)=>{ const r=indexedDB.open('ncaa_lineups',1); r.onupgradeneeded=()=>r.result.createObjectStore('kv'); r.onsuccess=()=>res(r.result); r.onerror=()=>rej(r.error); }); }
  return { async get(k){ const db=await open(); return new Promise((res,rej)=>{ const t=db.transaction('kv','readonly').objectStore('kv').get(k); t.onsuccess=()=>{db.close();res(t.result);}; t.onerror=()=>{db.close();rej(t.error);}; }); },
           async set(k,v){ const db=await open(); return new Promise((res,rej)=>{ const tx=db.transaction('kv','readwrite'); tx.objectStore('kv').put(v,k); tx.oncomplete=()=>{db.close();res();}; tx.onerror=()=>{db.close();rej(tx.error);}; }); },
           async del(k){ const db=await open(); return new Promise((res,rej)=>{ const tx=db.transaction('kv','readwrite'); tx.objectStore('kv').delete(k); tx.oncomplete=()=>{db.close();res();}; tx.onerror=()=>{db.close();rej(tx.error);}; }); } }; })();
/* state = {done:{gid:1}, miss:[...]} (small); each game's rows are their own record 'g_<gid>' */
async function loadState(conf){ const key='ncaa2_'+conf; let st=await KV.get(key);
  if(!st){ const ls=localStorage.getItem(key); if(ls){ try{ const old=JSON.parse(ls); st={done:old.done||{},miss:old.miss||[]}; const byg={}; for(const r of (old.rows||[])){ const gid=r.split('\t')[0]; (byg[gid]||(byg[gid]=[])).push(r); } for(const gid of Object.keys(byg)) await KV.set('g_'+gid,byg[gid]); await KV.set(key,st); localStorage.removeItem(key); }catch(e){ console.log('migration problem',e.message); } } }
  if(st&&st.rows){ const byg={}; for(const r of st.rows){ const gid=r.split('\t')[0]; (byg[gid]||(byg[gid]=[])).push(r); } for(const gid of Object.keys(byg)) await KV.set('g_'+gid,byg[gid]); delete st.rows; await KV.set(key,st); }
  return st||{done:{},miss:[]}; }
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
